import random
import threading

class LeastConnections:
    def __init__(self, backends: list[str]):
        self._lock = threading.Lock()
        self._active: dict[str, int] = {b: 0 for b in backends}
        self._healthy: set[str] = set(backends)

    def pick(self) -> str:
        # Power-of-two-choices: decorrelates concurrent pickers.
        # Trade-off: sometimes picks second-best to avoid herd + lock hold time.
        with self._lock:
            candidates = [b for b in self._active if b in self._healthy]
            if not candidates:
                raise RuntimeError("no healthy backends")
            a, b = random.sample(candidates, min(2, len(candidates)))
            chosen = a if self._active[a] <= self._active[b] else b
            self._active[chosen] += 1
            return chosen

    def release(self, backend: str) -> None:
        # Must be called on EVERY terminal path: response, error, timeout, abort.
        with self._lock:
            self._active[backend] = max(0, self._active.get(backend, 0) - 1)

    def set_healthy(self, backend: str, healthy: bool) -> None:
        with self._lock:
            if healthy:
                self._healthy.add(backend)
            else:
                self._healthy.discard(backend)
